const recentTopics = $('PostgreSQL - Buscar Temas Recentes').all().map(i => (i.json.topic || '').toLowerCase());

const techCategories = [
  'Inteligencia Artificial / Machine Learning',
  'Desenvolvimento Web & Mobile',
  'Ferramentas & Produtividade',
  'Cloud & DevOps',
  'Ciberseguranca',
  'Open Source & Comunidade',
  'Carreira Tech & Mercado',
  'Hardware & IoT',
  'Blockchain & Web3',
  'Startups & Inovacao',
  'Banco de Dados & Analytics',
  'UX/UI & Design'
];

const now = new Date();
const startOfYear = new Date(now.getFullYear(), 0, 0);
const diff = now - startOfYear;
const dayOfYear = Math.floor(diff / (1000 * 60 * 60 * 24));
const categoryIndex = dayOfYear % techCategories.length;
const todayCategory = techCategories[categoryIndex];

const items = [];

// 1. Process TechCrunch
const tcData = $('TechCrunch - RSS Feed (Gratis)').first().json;
if (tcData && tcData.rss && tcData.rss.channel && tcData.rss.channel.item) {
  const tcItems = Array.isArray(tcData.rss.channel.item) ? tcData.rss.channel.item : [tcData.rss.channel.item];
  tcItems.slice(0, 5).forEach(item => {
    items.push({ source: 'TechCrunch', title: item.title, link: item.link, desc: item.description });
  });
}

// 2. Process VentureBeat
const vbData = $('VentureBeat - AI Feed (Gratis)').first().json;
if (vbData && vbData.rss && vbData.rss.channel && vbData.rss.channel.item) {
  const vbItems = Array.isArray(vbData.rss.channel.item) ? vbData.rss.channel.item : [vbData.rss.channel.item];
  vbItems.slice(0, 5).forEach(item => {
    items.push({ source: 'VentureBeat', title: item.title, link: item.link, desc: item.description });
  });
}

// Filter by semantic similarity (>50% word overlap = duplicate)
const uniqueItems = items.filter(item => {
  const titleLower = (item.title || '').toLowerCase();
  const titleWords = titleLower.split(/\s+/).filter(w => w.length > 3);
  if (titleWords.length === 0) return true;
  return !recentTopics.some(prev => {
    const prevWords = prev.split(/\s+/).filter(w => w.length > 3);
    const matches = prevWords.filter(w => titleWords.includes(w)).length;
    const totalUnique = [...new Set([...prevWords, ...titleWords])].length;
    return totalUnique > 0 && (matches / totalUnique) > 0.5;
  });
});

// Shuffle for variety
const shuffled = uniqueItems.sort(() => Math.random() - 0.5);

return [{
  json: {
    candidate_articles: shuffled.slice(0, 8),
    today_category: todayCategory,
    day_of_year: dayOfYear
  }
}];

